// n8n Code node: Prepare Data
// Expected input: Extract From File output, plus original Form Trigger fields.
// Update the node name in $('AI Resume Optimizer Form') if you rename the trigger.

const extracted = $input.first()?.json ?? {};
const form = $('AI Resume Optimizer Form').first()?.json ?? {};

function cleanText(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\r\n?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkSentences(text, sentencesPerChunk = 3) {
  const sentences = text
    .split(/(?<=[.!?])\s+/)
    .map(s => s.trim())
    .filter(s => s.length > 20);

  const chunks = [];
  for (let i = 0; i < sentences.length; i += sentencesPerChunk) {
    const chunk = sentences.slice(i, i + sentencesPerChunk).join(' ');
    if (chunk) chunks.push(chunk);
  }
  return chunks.length ? chunks : (text.length > 0 ? [text] : []);
}

const resume = cleanText(
  extracted.text ?? extracted.extractedText ?? extracted.data ?? ''
);
const jobDescription = cleanText(
  form["Job Description"] ?? form.jobDescription ?? form.job_description ?? ''
);
const targetRole = cleanText(form["Target Role"] ?? form.targetRole ?? '');

if (!resume) {
  throw new Error(
    'No readable text was extracted from the uploaded PDF. Use a text-based PDF or add an OCR service for scanned resumes.'
  );
}
if (!jobDescription) {
  throw new Error('Job Description is required.');
}

const resumeChunks = chunkSentences(resume);
const jdChunks = chunkSentences(jobDescription);

if (!resumeChunks.length || !jdChunks.length) {
  throw new Error('Unable to create text chunks from the resume or job description.');
}

const allChunks = [...resumeChunks, ...jdChunks];

return [{
  json: {
    resume,
    jobDescription,
    targetRole,
    resumeChunks,
    jdChunks,
    resumeChunkCount: resumeChunks.length,
    jdChunkCount: jdChunks.length,
    embeddingRequests: allChunks.map(text => ({
      model: 'models/gemini-embedding-001',
      content: { parts: [{ text }] },
      outputDimensionality: 768
    }))
  }
}];

// n8n Code node: Calculate Semantic Similarity
// Expects the Gemini batchEmbedContents response in $input and Prepare Data upstream.

const prepared = $('Prepare Data').first().json;
const response = $input.first().json;
const embeddings = response.embeddings ?? response.data ?? [];

const resumeCount = prepared.resumeChunks.length;
const jdCount = prepared.jdChunks.length;
const expectedCount = resumeCount + jdCount;

if (!Array.isArray(embeddings) || embeddings.length !== expectedCount) {
  throw new Error(`Embedding count mismatch. Expected ${expectedCount}, received ${embeddings.length}.`);
}

const vectors = embeddings.map((item, index) => {
  const values = item.values ?? item.embedding?.values ?? item.embedding;
  if (!Array.isArray(values) || values.length === 0) {
    throw new Error(`Missing embedding vector at position ${index}.`);
  }
  return values;
});

const resumeVectors = vectors.slice(0, resumeCount);
const jdVectors = vectors.slice(resumeCount);

function cosine(a, b) {
  if (a.length !== b.length) throw new Error('Embedding dimensions do not match.');
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denominator = Math.sqrt(normA) * Math.sqrt(normB);
  return denominator === 0 ? 0 : dot / denominator;
}

const threshold = 0.45;
const matches = jdVectors.map((jdVector, index) => {
  let bestScore = -1;
  let bestIndex = -1;
  resumeVectors.forEach((resumeVector, resumeIndex) => {
    const score = cosine(jdVector, resumeVector);
    if (score > bestScore) {
      bestScore = score;
      bestIndex = resumeIndex;
    }
  });
  return {
    jdChunk: prepared.jdChunks[index],
    bestResumeChunk: prepared.resumeChunks[bestIndex] ?? '',
    similarity: Math.max(0, bestScore),
    matchedResumeChunkIndex: bestIndex
  };
});

const average = matches.reduce((sum, item) => sum + item.similarity, 0) / matches.length;
const semanticScore = Math.round(average * 100);
const weakRequirements = matches
  .filter(item => item.similarity < threshold)
  .map(item => item.jdChunk);

return [{
  json: {
    resume: prepared.resume,
    jobDescription: prepared.jobDescription,
    targetRole: prepared.targetRole,
    semanticScore,
    weakRequirements,
    chunkMatches: matches,
    similarityThreshold: threshold
  }
}];

// n8n Code node: Calculate Final Score
// Expects parsed Gemini JSON from the preceding LLM HTTP Request.

const semantic = $('Calculate Semantic Similarity').first().json;
const raw = $input.first().json;

function extractText(payload) {
  if (typeof payload === 'string') return payload;
  return payload.candidates?.[0]?.content?.parts?.map(p => p.text ?? '').join('\n')
    ?? payload.text
    ?? payload.output
    ?? '';
}

const text = extractText(raw).trim();
let evaluation;
try {
  const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  evaluation = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Could not parse Gemini evaluation as JSON: ${error.message}. Raw response: ${text.slice(0, 500)}`);
}

const clamp = value => Math.max(0, Math.min(100, Number(value) || 0));
const skills = clamp(evaluation.skills_score);
const roleMatch = clamp(evaluation.role_match_score);
const experience = clamp(evaluation.experience_score);
const semanticScore = clamp(semantic.semanticScore);

const finalScore = Math.round(
  0.40 * semanticScore +
  0.30 * skills +
  0.20 * roleMatch +
  0.10 * experience
);

const verdict = finalScore >= 80
  ? 'Strong Match'
  : finalScore >= 60
    ? 'Moderate Match'
    : 'Weak Match';

return [{
  json: {
    project: 'AI Resume Optimizer',
    targetRole: semantic.targetRole || evaluation.target_role || 'Not specified',
    finalScore,
    verdict,
    componentScores: {
      semantic: semanticScore,
      skills,
      roleMatch,
      experience
    },
    matchedSkills: evaluation.matched_skills ?? [],
    missingSkills: evaluation.missing_skills ?? [],
    roleFocusFeedback: evaluation.role_focus_feedback ?? '',
    projectFeedback: evaluation.project_feedback ?? '',
    rewriteSuggestions: evaluation.rewrite_suggestions ?? [],
    topPriorities: evaluation.top_priorities ?? [],
    weakRequirements: semantic.weakRequirements,
    chunkMatches: semantic.chunkMatches,
    disclaimer: 'This is an advisory estimate based on the supplied resume and job description, not a hiring decision or a guarantee of ATS performance.'
  }
}];
